<section class="search-page"><div class="section-heading"><div><span class="eyebrow">The best part is people</span><h1>Find your people</h1></div></div>
    <form class="directory-search" action="<?= e(url(['page' => 'search-users'])) ?>" method="get"><input type="hidden" name="page" value="search-users"><i class="bi bi-search"></i><input type="search" name="q" value="<?= e($query) ?>" placeholder="Try a name or username" aria-label="Search by name or username"><button class="button button-primary" type="submit">Search</button></form>
    <?php if ($query !== ''): ?><p class="result-count"><?= count($users) ?> <?= count($users) === 1 ? 'person' : 'people' ?> found for “<?= e($query) ?>”</p><?php endif; ?>
    <div class="people-grid"><?php foreach ($users as $person): ?><a class="directory-person" href="<?= e(url(['page' => 'profile', 'username' => $person['username']])) ?>"><?php if (!empty($person['profile_image'])): ?><img class="avatar" src="public/uploads/<?= e($person['profile_image']) ?>" alt=""><?php else: ?><span class="avatar avatar-initial"><?= e(strtoupper(substr($person['full_name'], 0, 1))) ?></span><?php endif; ?><span><strong><?= e($person['full_name']) ?></strong><small>@<?= e($person['username']) ?></small><span class="person-bio"><?= e($person['bio'] ?: 'A new face in the neighborhood.') ?></span></span><i class="bi bi-arrow-up-right"></i></a><?php endforeach; ?></div>
    <?php if ($query !== '' && !$users): ?><div class="empty-state"><span class="empty-icon"><i class="bi bi-search"></i></span><h2>No matches this time.</h2><p>Try a shorter name or a different spelling.</p></div><?php endif; ?>
</section>